const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the date of interest.
  const dateStart = '2020-08-06';
  const dateEnd = '2020-08-07';

  // Find the geometry for the Sakha Republic.
  const adminBoundaries = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const sakha = adminBoundaries.filter(ee.Filter.eq('ADM1_NAME', 'Sakha (Yakutiya), Respublika'));

  // Validate that the geometry was found.
  if (sakha.size().getInfo() === 0) {
      console.log('Error: Could not find geometry for Sakha Republic.');
      console.log('D');
      return;
  }
  const geometry = sakha.geometry();

  // 2. Data Acquisition
  // Use the MODIS Thermal Anomalies/Fire collection. It provides point data for fires.
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML')
      .filterDate(dateStart, dateEnd)
      .filterBounds(geometry);

  // The 'select' is crucial. We need the fire mask band.
  const fireImage = fireCollection.select('MaxFRP').first(); // Using MaxFRP as a representative band to count pixels

  // 3. Processing & Calculation
  // We don't need to mask clouds as the product is already a fire detection product.
  // We count the number of fire points (which are represented as pixels in the ImageCollection).
  // A simple count reducer is sufficient. We don't need to filter by confidence for this question.

  if (!fireImage.getInfo()) {
      console.log('No fire data image found for the specified date.');
      console.log('Active Fires: 0');
      // 0 is not > 8, so the answer is No.
      console.log('B');
      return;
  }

  const fireCountStats = fireImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000, // Native resolution of MODIS fire product is 1km
      maxPixels: 1e9
  });

  const fireCount = fireCountStats.get('MaxFRP').getInfo();

  // 4. Validation & Final Answer
  if (fireCount === null) {
      console.log('Could not calculate fire count.');
      console.log('C3');
      return;
  }

  console.log(`Date: ${dateStart}`);
  console.log(`Location: Sakha Republic`);
  console.log(`Active Fires Detected: ${fireCount}`);

  if (fireCount > 8) {
      console.log('A');
  } else {
      console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log('D');
});
